            if (data.name === "toggleKneel") return null;
            if (data.name === "mapMove") return object(data.pos) && Number.isFinite(data.pos.x) && Number.isFinite(data.pos.y) ? null : "bcc";
            if (data.name === "sendMessage") return typeof data.message === "string" && data.message.length <= 10000 && !data.message.startsWith("(") ? null : "bcc";
